const input = $input.first().json;
const msg = input.message;

let attachments = [];
let messageType = "text";

if (msg.document) {
  messageType = "document";
  attachments.push({
    file_id: msg.document.file_id,
    file_name: msg.document.file_name || "document",
    mime_type: msg.document.mime_type || "application/octet-stream",
    file_size: msg.document.file_size || 0
  });
} else if (msg.photo && msg.photo.length > 0) {
  messageType = "photo";
  const largest = msg.photo[msg.photo.length - 1];
  attachments.push({
    file_id: largest.file_id,
    file_name: `photo_${largest.file_id}.jpg`,
    mime_type: "image/jpeg",
    file_size: largest.file_size || 0
  });
} else if (msg.text) {
  messageType = "text";
}

return [
  {
    json: {
      channel: "telegram",
      message_id: String(msg.message_id),
      conversation_id: String(msg.chat.id),
      sender: {
        id: String(msg.from.id),
        name: `${msg.from.first_name || ""} ${msg.from.last_name || ""}`.trim()
      },
      message: {
        type: messageType,
        text: msg.text || msg.caption || ""
      },
      timestamp: msg.date,
      attachments: attachments,
      metadata: {
        telegram_update_id: input.update_id
      }
    }
  }
];

const borrower = $('Borrower').first().json;
const broker = $('Broker').first().json;
const applicationBorrower = $('Application Borrower').first().json;
const loanApplication = $('Loan Application').first().json;
const conversationSession = $('Conversation Session').first().json;
const workflowInstance = $('Workflow Instance').first().json;

const checklistRows = $('Document Checklist').all().map(i => i.json);
const documentTypes = $('Document Type').all().map(i => i.json);

const typeById = {};
for (const t of documentTypes) typeById[t.id] = t;

const requiredDocuments = checklistRows.map(c => {
  const t = typeById[c.document_type_id] || {};
  return {
    checklist_id: c.id,
    document_type_id: c.document_type_id,
    document_type_code: t.code || null,
    document_type_name: t.name || null,
    status: c.status,
    is_required: c.is_required
  };
});

const conversationHistory = $('Recent Conversation History').all().map(i => i.json);
const telegramContext = $('Extract Telegram Context').first().json;

return [
  {
    json: {
      borrower,
      broker,
      application_borrower: applicationBorrower,
      loan_application: loanApplication,
      conversation_session: conversationSession,
      workflow_instance: workflowInstance,
      required_documents: requiredDocuments,
      conversation_history: conversationHistory,

      latest_message: {
        channel: telegramContext.channel,
        text: telegramContext.message.text,
        message_type: telegramContext.message.type,
        sender_id: telegramContext.sender.id,
        sender_name: telegramContext.sender.name,
        conversation_id: telegramContext.conversation_id,
        message_id: telegramContext.message_id,
        timestamp: telegramContext.timestamp,
        attachments: telegramContext.attachments || []
      }
    }
  }
];

// MVP: single channel (Telegram). Passthrough today.
// When WhatsApp/other channels are added post-MVP, this node
// resolves which borrower lookup field to use per channel.
return $input.all();

const data = $input.first().json;

const requiredFields = [
  "channel",
  "message_id",
  "conversation_id",
  "sender",
  "message",
  "timestamp"
];

for (const field of requiredFields) {
  if (!data[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

if (!data.sender.id) {
  throw new Error("Missing sender.id");
}

if (!data.sender.name) {
  throw new Error("Missing sender.name");
}

const allowedTypes = ["text", "document", "photo"];
if (!allowedTypes.includes(data.message.type)) {
  throw new Error(`Unsupported message type: ${data.message.type}`);
}

const hasText = data.message.text && data.message.text.trim() !== "";
const hasAttachment = data.attachments && data.attachments.length > 0;

if (!hasText && !hasAttachment) {
  throw new Error("Empty message received");
}

return [
  {
    json: {
      ...data,
      validation: {
        status: "passed",
        validated_at: new Date().toISOString()
      }
    }
  }
];

const input = $input.first().json;

return [
{
json:{
chat_id: input.borrower.telegram_chat_id,
text: input.reply
}
}
];

const base = $('Normalize AI Response').item.json;
let content = '';
try { content = $input.first().json.choices[0].message.content; } catch (e) {}
let vision = { predicted_code: 'UNKNOWN', confidence: 0, reason: 'parse_failed' };
try { vision = JSON.parse(content); } catch (e) {}
const attachments = base.attachments || [];
const textGuess = ((base.metadata && base.metadata.document_type) || '').toUpperCase();
const visionCode = (vision && vision.predicted_code) ? String(vision.predicted_code).toUpperCase() : 'UNKNOWN';
const docType = (visionCode && visionCode !== 'UNKNOWN') ? visionCode : textGuess;
const match = (base.required_documents || []).find(d => d.document_type_code === docType && ['PENDING','REQUESTED'].includes(d.status));
return [{
  json: {
    ...base,
    vision: vision,
    predicted_code: docType,
    classification_source: (visionCode && visionCode !== 'UNKNOWN') ? 'vision' : (textGuess ? 'text' : 'none'),
    match_found: !!match && attachments.length > 0,
    checklist_id: match ? match.checklist_id : null,
    attachment: attachments[0] || null
  },
  binary: $('Download Telegram File').item.binary,
  pairedItem: { item: 0 }
}];

const data = $input.first().json;
return [
  {
    json: {
      ...data,
      unmatched_document: true
    }
  }
];

const items = $input.all();
const sorted = items
  .map(i => i.json)
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
  .slice(0, 15);
return sorted.map(json => ({ json }));

const attachment = $('Match Checklist Item').item.json.attachment;
const allowedMimeTypes = ['application/pdf', 'image/jpeg', 'image/png'];
const maxSizeBytes = 10 * 1024 * 1024;
const errors = [];

if (!attachment || !allowedMimeTypes.includes(attachment.mime_type)) {
  errors.push('unsupported_file_type');
}
if (!attachment || !attachment.file_size || attachment.file_size === 0) {
  errors.push('empty_file');
}
if (attachment && attachment.file_size > maxSizeBytes) {
  errors.push('file_too_large');
}

return [{
  json: {
    ...$input.first().json,
    is_valid: errors.length === 0,
    validation_errors: errors
  },
  binary: $input.first().binary
}];

return [{
  json: {
    document_id: $('Insert Document Record').item.json.id,
    storage_path: $('Insert Document Record').item.json.storage_path,
    mime_type: $('Insert Document Record').item.json.mime_type,
    application_id: $('Normalize AI Response').item.json.loan_application.id
  }
}];

const item = $input.first();
const bin = (item.binary && item.binary.data) ? item.binary.data : null;
const base = $('Normalize AI Response').item.json;
const reqs = (base.required_documents || []).filter(d => ['PENDING','REQUESTED'].includes(d.status));
const known = {
  AADHAAR: "AADHAAR = Aadhaar Card: Indian UIDAI national ID; 12-digit Aadhaar number (often shown as 1234 5678 9012), UIDAI logo, name, date of birth, gender, address, and a photo.",
  PAN: "PAN = PAN Card: Indian Income Tax PAN card; a 10-character alphanumeric PAN like ABCDE1234F, cardholder name, father's name, date of birth, and 'INCOME TAX DEPARTMENT' / 'GOVT. OF INDIA' text.",
  PASSPORT: "PASSPORT = Passport: government travel document with a photo, passport number, nationality, and two machine-readable (MRZ) lines at the bottom.",
  COMPANY_FINANCIALS: "COMPANY_FINANCIALS = Company Financial Statements: balance sheet, profit-and-loss, or financial report pages."
};
const codes = reqs.map(d => d.document_type_code);
const candidateText = codes.map(c => known[c] || (c + ' = ' + c)).join('\n');
const mime = (bin && bin.mimeType) || (base.attachments && base.attachments[0] && base.attachments[0].mime_type) || 'image/jpeg';
const b64 = bin ? bin.data : '';
const dataUri = 'data:' + mime + ';base64,' + b64;
const prompt = 'You are classifying a document image uploaded by a mortgage borrower who did NOT label it.\n\nDecide which ONE of these expected document types the image is:\n' + candidateText + '\n\nRespond with STRICT JSON only: {"predicted_code":"<CODE or UNKNOWN>","confidence":<number 0-1>,"reason":"<short reason>"}\nThe code MUST be exactly one of: ' + codes.join(', ') + ', or UNKNOWN if the image is none of them or is unreadable.';
return [{
  json: { data_uri: dataUri, mime: mime, candidate_codes: codes, prompt: prompt },
  binary: item.binary,
  pairedItem: { item: 0 }
}];
